import type * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

/**
 * Status mark: a dot plus label. Tones read theme slots only: the status roles
 * --success, --warning, --info and --destructive.
 */
const statusMarkVariants = cva(
  "inline-flex w-fit shrink-0 items-center gap-1.5 rounded-4xl border px-2 py-0.5 text-xs font-medium whitespace-nowrap",
  {
    variants: {
      tone: {
        neutral: "border-border bg-muted text-muted-foreground [--status-mark:var(--muted-foreground)]",
        success: "border-[color-mix(in_oklch,var(--success)_30%,transparent)] bg-[color-mix(in_oklch,var(--success)_12%,transparent)] text-foreground [--status-mark:var(--success)]",
        warning: "border-[color-mix(in_oklch,var(--warning)_30%,transparent)] bg-[color-mix(in_oklch,var(--warning)_12%,transparent)] text-foreground [--status-mark:var(--warning)]",
        danger: "border-destructive/30 bg-destructive/10 text-destructive [--status-mark:var(--destructive)]",
        info: "border-[color-mix(in_oklch,var(--info)_30%,transparent)] bg-[color-mix(in_oklch,var(--info)_12%,transparent)] text-foreground [--status-mark:var(--info)]",
      },
    },
    defaultVariants: { tone: "neutral" },
  }
)

function StatusMark({
  className,
  tone = "neutral",
  children,
  ...props
}: React.ComponentProps<"span"> & VariantProps<typeof statusMarkVariants>) {
  return (
    <span data-slot="status-mark" data-tone={tone} className={cn(statusMarkVariants({ tone }), className)} {...props}>
      <span aria-hidden="true" data-slot="status-mark-indicator" className="size-2 shrink-0 rounded-full bg-(--status-mark)" />
      {children}
    </span>
  )
}

export { StatusMark, statusMarkVariants }
